function closeModal(){$('#modal-wrap').classList.add('hidden')}function showModal(html){$('#modal').innerHTML=html;$('#modal-wrap').classList.remove('hidden')}
const enemies=[{name:'Registry Hounds',kind:'Goblin tracker & patrol captain',hp:76,max:76,damage:12},{name:'Ser Caldrin',kind:'Fifth-tier light-hunter',hp:98,max:98,damage:15},{name:'The Gate-Devourer',kind:'Demon wearing a dragon’s shape',hp:142,max:142,damage:18}];
function beginFight(n){g.battle=n;g.enemy={...enemies[n]};g.stage='fight'+(n+1);g.hp=Math.min(g.maxHp,g.hp+15);g.mp=Math.min(g.maxMp,g.mp+18);log(`${g.enemy.name} stands in your way.`);render()}
function winFight(){let b=g.battle;g.enemy=null;g.xp+=b===2?50:35;g.gold+=b===0?12:b===1?20:55;g.renown+=b===2?3:1;g.hp=Math.min(g.maxHp,g.hp+17);g.mp=Math.min(g.maxMp,g.mp+18);log(`${enemies[b].name} defeated. You gather experience and a monster-core.`);if(b===0)g.stage='interlude1';else if(b===1)g.stage='coreTrial';else{g.stage='ending';g.ending=true}render()}
function spellData(){let e=g.element;const map={Fire:{name:'Cinder Lance',desc:'A focused bolt of fire; heavy damage.',dmg:29,cost:12},Water:{name:'Riptide',desc:'Crashing water; damage and restore vitality.',dmg:21,cost:11},Earth:{name:'Thornwake',desc:'Roots and stone; damage and gain a ward.',dmg:22,cost:11},Wind:{name:'Gale Shear',desc:'A cutting gust; swift damage and evade.',dmg:23,cost:11}};return map[e]||map.Fire}
function perform(type){if(!g.enemy)return;let e=g.enemy,p=g;let msg='';if(type==='strike'){let d=15+Math.floor(Math.random()*7)+(p.weak?8:0);e.hp-=d;msg=`You strike with your weapon for ${d} damage.`}
if(type==='spell'){let s=spellData();if(p.mp<s.cost){toast('Not enough core reserve.');return}p.mp-=s.cost;let d=s.dmg+Math.floor(Math.random()*10)+(p.tier>1?5:0)+(p.weak?8:0);e.hp-=d;msg=`${s.name} hits for ${d} damage.`;if(p.element==='Water'){p.hp=Math.min(p.maxHp,p.hp+8);msg+=' The current mends 8 vitality.'}if(p.element==='Earth'){p.shield+=9;msg+=' A stone ward absorbs 9.'}if(p.element==='Wind'){p.dodge=true;msg+=' You become hard to pin down.'}}
if(type==='talent'){if(p.mp<8){toast('Not enough core reserve.');return}p.mp-=8;let t=p.talent;if(t==='Dreamwalker'){p.weak=true;p.mp=Math.min(p.maxMp,p.mp+8);msg='You slip into the enemy’s dream. Their next strike falters; your reserve steadies.'}else if(t==='Medium'){p.hp=Math.min(p.maxHp,p.hp+17);p.weak=true;msg='A dead voice reveals their weakness. Restore 17 vitality; your next strike finds it.'}else if(t==='Astral'){p.dodge=true;p.weak=true;msg='Your astral self leaves the body. Evade the next blow and mark their weakness.'}else{p.dodge=true;let d=18+Math.floor(Math.random()*7);e.hp-=d;msg=`You blink behind your enemy and deal ${d} damage.`}}
if(type==='item'){if(p.gold<10){toast('A healing draught costs 10 coin.');return}p.gold-=10;p.hp=Math.min(p.maxHp,p.hp+28);msg='You drink a healing draught: +28 vitality.'}
p.weak=false;log(msg);if(e.hp<=0){e.hp=0;log(`${e.name} falls.`);render();setTimeout(winFight,320);return}let damage=e.damage+Math.floor(Math.random()*6);if(p.dodge){damage=0;p.dodge=false;msg+=' You evade their counterattack!'}else if(p.shield){let block=Math.min(p.shield,damage);p.shield-=block;damage-=block;msg+=` Your ward absorbs ${block}.`}p.hp=Math.max(0,p.hp-damage);log(`${e.name} counters for ${damage} damage.`);if(p.hp<=0){g.stage='defeat';log('Your core flickers at the edge of collapse.');}render()}
function act(key){if(key==='inspect'){g.gold+=3;g.study=true;g.acts.push('surveyed');log('You map a safe route through the old aqueduct (+3 coin).');toast('Found 3 coin and a safer route.');render();return}if(key==='rite'){g.tier=1;g.xp=12;g.stage='afterRite';log(`A tier-one ${g.element} core forms around your heart.`);render();return}if(key==='hide'){g.renown+=1;g.gold+=5;g.route='quiet';log('You mask your core and escape with help from the poor quarter.');toast('Core hidden. +5 coin, +1 renown.');beginFight(0);return}if(key==='reveal'){g.renown+=2;g.hp-=8;g.route='bold';log('You reveal your core. The masters’ rune lashes back, but the crowd sees everything.');toast('Your defiance costs 8 vitality, but the city saw.');beginFight(0);return}if(key==='oath'){g.renown-=1;g.gold+=8;g.route='oath';log('You repeat the house oath and slip away with the registry’s seal.');toast('House seal: +8 coin.');beginFight(0);return}if(key==='refuse'){g.renown+=2;g.route='refuse';log('You refuse your family’s command. Your house name is no shield now.');beginFight(0);return}if(key==='protect'){g.hp=Math.min(g.maxHp,g.hp+20);g.renown+=2;g.gold+=3;g.choice='protect';log('You give the core to the family and protect them (+20 vitality, +2 renown).');toast('The family hides you. +20 vitality.');beginFight(1);return}if(key==='harvest'){g.gold+=18;g.mp=Math.min(g.maxMp,g.mp+15);g.choice='harvest';log('You keep the core for alchemy (+18 coin, +15 reserve).');toast('Monster-core harvested. +18 coin.');beginFight(1);return}if(key==='study'){g.talent='Medium';g.mp=Math.min(g.maxMp,g.mp+12);g.study=true;log('A voice from the dead teaches you where Caldrin’s light will fall. You learn to speak with the dead.');toast('Rare art learned: speak with the dead.');beginFight(1);return}if(key==='dream'){g.talent='Dreamwalker';g.weak=true;log('You enter the dream of the city and return with the shape of your own fear.');beginFight(1);return}if(key==='careful'){g.tier=2;g.maxMp+=18;g.mp=g.maxMp;g.maxHp+=12;g.hp=Math.min(g.maxHp,g.hp+24);g.xp=0;log('You weave the second core slowly. Tier Two: stable, durable, alive.');toast('Tier Two attained safely.');beginFight(2);return}if(key==='overdraw'){g.tier=2;g.maxMp+=25;g.mp=g.maxMp;g.maxHp-=18;g.hp=Math.max(25,g.hp-22);g.xp=0;g.renown+=1;log('You force the second core into place. Tier Two power surges—your heart nearly gives out.');toast('Overdraw: more reserve, less vitality.');beginFight(2);return}if(key==='restart'){g=initial();identityModal();return}if(key==='retry'){g.hp=Math.ceil(g.maxHp*.7);g.mp=Math.ceil(g.maxMp*.7);if(g.stage==='defeat'){let n=Math.max(0,g.battle);g.stage='fight'+(n+1);g.enemy={...enemies[n]};g.enemy.hp=Math.ceil(g.enemy.maxHp*.72);g.enemy.max=g.enemy.maxHp;}log('You rally with a fraction of your strength. The enemy is wounded too.');render();return}if(key==='spell'||key==='strike'||key==='talent'||key==='item'){perform(key);return}}

