if(key==='spell'||key==='strike'||key==='talent'||key==='item'){perform(key);return}}
function setStory(s){$('#chapter').textContent=s.chapter;$('#title').textContent=s.title;$('#subtitle').textContent=s.subtitle;$('#chapter-tag').textContent=s.tag;$('#figure').textContent=s.figure;$('#narrative').innerHTML=s.text;$('#quest-title').textContent=s.quest;$('#quest-text').textContent=s.goal}
function render(){if(!g.started)return;let s=story[g.stage]||story.arrival;setStory(s);$('#combat-ui').classList.add('hidden');$('#narrative').classList.remove('hidden');$('#actions').innerHTML='';let opts=[];
if(g.stage==='arrival'){opts=[['inspect','Scout the lower city','Search the old aqueduct for a safe route. Earn a little coin before the rite.',''],['rite','Enter the Twelfth-Year Rite','Face five fifth-tier masters and awaken the core within your heart.','primary']]}
if(g.stage==='afterRite'){if(g.origin==='poor')opts=[['hide','Hide the spark','Keep your core secret. The poor quarter will help you flee.','primary'],['reveal','Let them see what you are','Defy the masters in front of the crowd. Risk a painful rune backlash.','danger']];else opts=[['oath','Take your house’s oath','Use your name to leave the rite. A quiet choice, for now.','primary'],['refuse','Refuse your family','Stand with the hunted, even if your house casts you out.','']]}
if(g.stage==='fight1'||g.stage==='fight2'||g.stage==='fight3'){if(!g.enemy)g.enemy={...enemies[g.battle]};$('#narrative').classList.add('hidden');let enemy=g.enemy;let combat=$('#combat-ui');combat.classList.remove('hidden');combat.innerHTML=`<div class="combat-top"><div class="eyebrow">YOUR TURN • CHOOSE AN ACTION</div><div class="enemy-tag">${enemy.kind}</div></div><div class="enemy-card"><div><div class="enemy-name">${enemy.name}</div><div class="enemy-hp">${enemy.hp} / ${enemy.maxHp} vitality</div></div><div style="font-size:24px">${g.battle===0?'👹':g.battle===1?'🛡️':'🐉'}</div></div><div class="meter"><div class="track"><div class="fill hp-fill" style="width:${100*enemy.hp/enemy.maxHp}%"></div></div></div><div class="combat-actions">${combatButton('strike','Weapon strike','Reliable • no reserve cost','⚔')} ${combatButton('spell',spellData().name,spellData().desc+' ('+spellData().cost+' reserve)','✦')} ${combatButton('talent',talentName(),talentDesc(),'◈')} ${combatButton('item','Healing draught','Restore 28 vitality • costs 10 coin','⚗')}</div>`;combat.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>act(b.dataset.act));}
if(g.stage==='interlude1')opts=[['protect','Protect the family','Give up the monster-core. Gain an ally and recover vitality.','primary'],['harvest','Harvest the core','Keep it for alchemy. Earn coin and recover reserve.',''],['study','Listen to the dead','Spend a moment with the souls trapped in the core. Learn a rare art.','']];
if(g.stage==='coreTrial')opts=[['careful','Weave the core carefully','Tier Two, steadily formed. More durable; no heart-burst risk.','primary'],['overdraw','Overdraw the heart','Force a powerful second core. Gain reserve, risk lasting damage.','danger']];
if(g.stage==='ending'){let tone=g.choice==='protect'?'You gave away a monster-core to protect a family. Their neighbors gather. The registry can no longer make you disappear quietly.':g.choice==='harvest'?'You used the monster-core to fund your next steps. Alchemists talk, and coin opens doors that kindness cannot.':'You walked out with no master, no house oath, and your own heart still beating.';let origin=g.origin==='poor'?'Born among the hunted, you proved the poor can shape magic without permission.':'Born to privilege, you broke the agreement that kept it safe for only the rich.';let tierline=`Your ${g.element} core reaches Tier ${g.tier}. ${g.talent==='Dreamwalker'?'You can enter dreams.':g.talent==='Medium'?'You can speak to the dead.':g.talent==='Astral'?'Your astral self can leave your body.':'You can teleport in a blink.'}`;$('#narrative').innerHTML=`${tone} ${origin} ${tierline} The demon gate is sealed; Caldrin’s report will not tell the whole truth. Across three continents, spies hear rumors of a new kind of mage. <em>Antrovia has changed—but its seven tiers and old wars remain.</em>`;opts=[['restart','Begin another life','Choose a different element and origin.','primary']]}
if(g.stage==='defeat'){ $('#narrative').innerHTML='Your core flickers. The enemy looms above you, and the world narrows to the beat of your heart. <em>Not yet.</em>';opts=[['retry','Rally and fight again','Return with 70% vitality and reserve; the foe is weakened too.','primary'],['restart','Begin another life','Try a different affinity or path.','']]}
opts.forEach(o=>$('#actions').appendChild(actionButton(...o)));updateSide();save()}
function combatButton(k,name,desc,icon){return `<button class="action" data-act="${k}"><span><strong>${icon} &nbsp;${name}</strong><small>${desc}</small></span><span class="arr">›</span></button>`}
