28: const enemies=[{name:'Registry Hounds',kind:'Goblin tracker & patrol captain',hp:76,max:76,damage:12},{name:'Ser Caldrin',kind:'Fifth-tier light-hunter',hp:98,max:98,damage:15},{name:'The Gate-Devourer',kind:'Demon wearing a dragon’s shape',hp:142,max:142,damage:18}];
29: function beginFight(n){g.battle=n;g.enemy={...enemies[n]};g.stage='fight'+(n+1);g.hp=Math.min(g.maxHp,g.hp+15);g.mp=Math.min(g.maxMp,g.mp+18);log(`${g.enemy.name} stands in your way.`);render()}
30: function winFight(){let b=g.battle;g.enemy=null;g.xp+=b===2?50:35;g.gold+=b===0?12:b===1?20:55;g.renown+=b===2?3:1;g.hp=Math.min(g.maxHp,g.hp+17);g.mp=Math.min(g.maxMp,g.mp+18);log(`${enemies[b].name} defeated. You gather experience and a monster-core.`);if(b===0)g.stage='interlude1';else if(b===1)g.stage='coreTrial';else{g.stage='ending';g.ending=true}render()}
31: function spellData(){let e=g.element;const map={Fire:{name:'Cinder Lance',desc:'A focused bolt of fire; heavy damage.',dmg:29,cost:12},Water:{name:'Riptide',desc:'Crashing water; damage and restore vitality.',dmg:21,cost:11},Earth:{name:'Thornwake',desc:'Roots and stone; damage and gain a ward.',dmg:22,cost:11},Wind:{name:'Gale Shear',desc:'A cutting gust; swift damage and evade.',dmg:23,cost:11}};return map[e]||map.Fire}
32: function perform(type){if(!g.enemy)return;let e=g.enemy,p=g;let msg='';if(type==='strike'){let d=15+Math.floor(Math.random()*7)+(p.weak?8:0);e.hp-=d;msg=`You strike with your weapon for ${d} damage.`}
33: if(type==='spell'){let s=spellData();if(p.mp<s.cost){toast('Not enough core reserve.');return}p.mp-=s.cost;let d=s.dmg+Math.floor(Math.random()*10)+(p.tier>1?5:0)+(p.weak?8:0);e.hp-=d;msg=`${s.name} hits for ${d} damage.`;if(p.element==='Water'){p.hp=Math.min(p.maxHp,p.hp+8);msg+=' The current mends 8 vitality.'}if(p.element==='Earth'){p.shield+=9;msg+=' A stone ward absorbs 9.'}if(p.element==='Wind'){p.dodge=true;msg+=' You become hard to pin down.'}}
34: if(type==='talent'){if(p.mp<8){toast('Not enough core reserve.');return}p.mp-=8;let t=p.talent;if(t==='Dreamwalker'){p.weak=true;p.mp=Math.min(p.maxMp,p.mp+8);msg='You slip into the enemy’s dream. Their next strike falters; your reserve steadies.'}else if(t==='Medium'){p.hp=Math.min(p.maxHp,p.hp+17);p.weak=true;msg='A dead voice reveals their weakness. Restore 17 vitality; your next strike finds it.'}else if(t==='Astral'){p.dodge=true;p.weak=true;msg='Your astral self leaves the body. Evade the next blow and mark their weakness.'}else{p.dodge=true;let d=18+Math.floor(Math.random()*7);e.hp-=d;msg=`You blink behind your enemy and deal ${d} damage.`}}
35: if(type==='light'||type==='dark'){if(p.mp<16){toast('Not enough core reserve.');return}p.mp-=16;if(type==='light'){let d=20+Math.floor(Math.random()*9);e.hp-=d;p.hp=Math.min(p.maxHp,p.hp+12);p.shield+=6;msg=`A light rune sears for ${d} damage, heals 12, and grants a ward.`}else{let d=37+Math.floor(Math.random()*10);e.hp-=d;p.hp=Math.max(1,p.hp-9);msg=`A dark-core rupture deals ${d} damage—but costs 9 vitality.`}}
