---
function identityModal(){chosenOrigin='poor';chosenElement='Fire';chosenWeapon='Blade';let modal=$('#modal');modal.innerHTML=`<div class="eyebrow">A NARRATIVE MAGIC RPG</div><h1>The heart of Antrovia</h1><p>You are transmigrated into a world where magic is inherited, power is measured in seven tiers, and the poor are hunted for the very gift nobles claim as their own. At twelve, five master mages will judge your heart.</p><div class="eyebrow" style="margin-top:20px">WHO WERE YOU BORN TO?</div><div class="choices"><button class="pick selected" data-origin="poor"><b>🌑 The unregistered poor</b><small>Your family carries the city on its back. Magic is forbidden to you; discovery means a hunt. Begin with extra street sense.</small></button><button class="pick" data-origin="noble"><b>🦚 A minor noble house</b><small>You have privilege, tutors, and a place at the rite. But your house expects obedience—and magic belongs to them.</small></button></div><div class="eyebrow">WHAT STIRS IN YOUR HEART?</div><div class="choices">${Object.values(elements).map(e=>`<button class="pick ${e.name==='Fire'?'selected':''}" data-element="${e.name==='Earth & Nature'?'Earth':e.name}"><b>${e.icon} ${e.name}</b><small>${e.desc}</small></button>`).join('')}</div><div class="eyebrow">CHOOSE YOUR WEAPON SPECIALIZATION</div><div class="choices">${Object.entries(weapons).map(([name,w])=>`<button class="pick ${name==='Blade'?'selected':''}" data-weapon="${name}"><b>${w.icon} ${name}</b><small>${w.desc}</small></button>`).join('')}</div><div class="modal-actions"><button class="action primary" id="begin"><span><strong>Enter Antrovia</strong><small>All magic begins with one core</small></span><span class="arr">→</span></button></div>`;modal.querySelectorAll('[data-origin]').forEach(b=>b.onclick=()=>{chosenOrigin=b.dataset.origin;modal.querySelectorAll('[data-origin]').forEach(x=>x.classList.toggle('selec

